window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-59673a3b23e440b6"]={"versions": [{"id": "FIG-59673a3b23e440b6", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsübergangsdiagramm (UML State Machine) der AUTOSAR Classic Platform zur Definition des DTC-Statusbits 7 (<code>WarningIndicatorRequested</code>) innerhalb des Diagnostic Event Managers (<code>Dem</code>). Das Diagramm visualisiert die normativen Zustandswechsel des Statusbits nach ISO 14229-1 bzw. AUTOSAR-DTC-Statusmasken-Logik.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände</strong>:\n<ul class=\"fig-list\"><li><code>Initial state</code>: Pseudozustand (Startzustand des DTC-Statusbytes).\n</li><li><code>WarningIndicatorRequested = FALSE</code>: Zustand bei inaktiver Warnanzeige-Anforderung (Bit 7 = 0).\n</li><li><code>WarningIndicatorRequested = TRUE</code>: Zustand bei aktiver Warnanzeige-Anforderung (Bit 7 = 1).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter</strong>:\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus</code> / <code>Dem_ReportErrorStatus</code>: API-Funktionen zur Fehlermeldung mit Parametern <code>EventId</code> und <code>EventStatus = DEM_EVENT_STATUS_FAILED</code>.\n</li><li>Warnkriterien (<code>WarningIndicator On-Criteria</code>, <code>WarningIndicator Off-Criteria</code>).\n</li><li><code>Latched failsafe</code>: Deaktivierungsbedingung bezüglich des sicherheitsrelevanten Verriegelungsverhaltens für den spezifischen DTC.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung</strong>:\n<ul class=\"fig-list\"><li>Eintritt vom <code>Initial state</code> über <code>Bit 7</code> direkt in den Zustand <code>WarningIndicatorRequested = FALSE</code>.\n</li></ul>\n</li><li><strong>Aktivierung (FALSE -&gt; TRUE)</strong>:\n<ul class=\"fig-list\"><li>Übergang erfolgt bei Funktionsaufruf <code>Dem_SetEventStatus(EventId, DEM_EVENT_STATUS_FAILED)</code> bzw. <code>Dem_ReportErrorStatus(EventId, DEM_EVENT_STATUS_FAILED)</code> in Verbindung mit der Erfüllung der parametrierten Einschaltkriterien (<code>WarningIndicator On-Criteria is Fulfilled</code>) unter Vorbehalt von Fußnote [B].\n</li></ul>\n</li><li><strong>Deaktivierung (TRUE -&gt; FALSE)</strong>:\n<ul class=\"fig-list\"><li>Übergang erfolgt bei Erfüllung der parametrierten Ausschaltkriterien (<code>WarningIndicator Off-Criteria is Fulfilled</code>) AND der Bedingung, dass keine Warnanzeige aufgrund von Latched-Failsafe für diesen DTC angefordert bleibt (<code>warning indicator not requested on due to Latched failsafe for particular DTC</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Definiert das standardkonforme Verhalten des Dem für das DTC-Statusbyte Bit 7 gemäß AUTOSAR-SWS Dem.\n</li><li>Relevanz für BSW-Entwickler: Die Anforderung der Warnanzeige (z. B. MIL oder fahrzeugspezifische Kontrollleuchten) ist an spezifische, im BSW konfigurierbare Ein- und Ausschaltkriterien (z. B. Bestätigungszyklen, Entprellung) gekoppelt.\n</li><li>Implementierungshinweis: Vor dem Zurücksetzen von Bit 7 auf <code>FALSE</code> muss geprüft werden, ob ein verriegelter Failsafe-Zustand (<code>Latched failsafe</code>) ein vorzeitiges Deaktivieren der Warnanzeige für das DTC verhindert.\n</li></ul>"}, {"id": "FIG-a4bd048c033255cb", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsübergangsdiagramm (UML State Machine) der AUTOSAR Classic Platform zur Definition des DTC-Statusbits 7 (<code>WarningIndicatorRequested</code>) innerhalb des Diagnostic Event Managers (<code>Dem</code>). Das Diagramm visualisiert die normativen Zustandswechsel des Statusbits nach ISO 14229-1 bzw. AUTOSAR-DTC-Statusmasken-Logik.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände</strong>:\n<ul class=\"fig-list\"><li><code>Initial state</code>: Pseudozustand (Startzustand des DTC-Statusbytes).\n</li><li><code>WarningIndicatorRequested = FALSE</code>: Zustand bei inaktiver Warnanzeige-Anforderung (Bit 7 = 0).\n</li><li><code>WarningIndicatorRequested = TRUE</code>: Zustand bei aktiver Warnanzeige-Anforderung (Bit 7 = 1).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter</strong>:\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus</code> / <code>Dem_ReportErrorStatus</code>: API-Funktionen zur Fehlermeldung mit Parametern <code>EventId</code> und <code>EventStatus = DEM_EVENT_STATUS_FAILED</code>.\n</li><li>Warnkriterien (<code>WarningIndicator On-Criteria</code>, <code>WarningIndicator Off-Criteria</code>).\n</li><li><code>Latched failsafe</code>: Deaktivierungsbedingung bezüglich des sicherheitsrelevanten Verriegelungsverhaltens für den spezifischen DTC.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung</strong>:\n<ul class=\"fig-list\"><li>Eintritt vom <code>Initial state</code> über <code>Bit 7</code> direkt in den Zustand <code>WarningIndicatorRequested = FALSE</code>.\n</li></ul>\n</li><li><strong>Aktivierung (FALSE -&gt; TRUE)</strong>:\n<ul class=\"fig-list\"><li>Übergang erfolgt bei Funktionsaufruf <code>Dem_SetEventStatus(EventId, DEM_EVENT_STATUS_FAILED)</code> bzw. <code>Dem_ReportErrorStatus(EventId, DEM_EVENT_STATUS_FAILED)</code> in Verbindung mit der Erfüllung der parametrierten Einschaltkriterien (<code>WarningIndicator On-Criteria is Fulfilled</code>) unter Vorbehalt von Fußnote [B].\n</li></ul>\n</li><li><strong>Deaktivierung (TRUE -&gt; FALSE)</strong>:\n<ul class=\"fig-list\"><li>Übergang erfolgt bei Erfüllung der parametrierten Ausschaltkriterien (<code>WarningIndicator Off-Criteria is Fulfilled</code>) AND der Bedingung, dass keine Warnanzeige aufgrund von Latched-Failsafe für diesen DTC angefordert bleibt (<code>warning indicator not requested on due to Latched failsafe for particular DTC</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Definiert das standardkonforme Verhalten des Dem für das DTC-Statusbyte Bit 7 gemäß AUTOSAR-SWS Dem.\n</li><li>Relevanz für BSW-Entwickler: Die Anforderung der Warnanzeige (z. B. MIL oder fahrzeugspezifische Kontrollleuchten) ist an spezifische, im BSW konfigurierbare Ein- und Ausschaltkriterien (z. B. Bestätigungszyklen, Entprellung) gekoppelt.\n</li><li>Implementierungshinweis: Vor dem Zurücksetzen von Bit 7 auf <code>FALSE</code> muss geprüft werden, ob ein verriegelter Failsafe-Zustand (<code>Latched failsafe</code>) ein vorzeitiges Deaktivieren der Warnanzeige für das DTC verhindert.\n</li></ul>"}], "trans": [{"from": "FIG-59673a3b23e440b6", "to": "FIG-a4bd048c033255cb", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
